/* The preprocessor benchmark input.
 *
 * Macros defined as each function needs them: constants, function-like
 * ones nested three deep, # and ##, one with __VA_ARGS__, one spread over
 * lines with backslashes, one taken back with #undef and given again; and
 * #if, #elif, #else, #ifdef, #ifndef and defined() over them. A real C file
 * is full of these, and no generated input had one: the preprocessor's
 * time went in unmeasured.
 *
 * Generated by generate.py and committed, so that a number from today can
 * be compared with one from last week. Returns 42.
 */

#define LIMIT_ANCHOR0 (0 + 12)
#define SQUARE_ANCHOR0(x) ((x) * (x))
#define CLAMP_ANCHOR0(v, lo, hi) ((v) < (lo) ? (lo) : (v) > (hi) ? (hi) : (v))

int scale_anchor(int value) {
    int squared = SQUARE_ANCHOR0(value % 7);

    return CLAMP_ANCHOR0(squared, 1, LIMIT_ANCHOR0) + LIMIT_ANCHOR0 / 2;
}

#define MODE_BUFFER1 1
#if MODE_BUFFER1 == 0
# define STEP_BUFFER1 1
#elif MODE_BUFFER1 == 1
# define STEP_BUFFER1 2
#else
# define STEP_BUFFER1 3
#endif
#ifndef UNUSED_BUFFER1
# define UNUSED_BUFFER1 0
#endif

#ifdef STEP_BUFFER1
int walk_buffer(int count) {
    int total = UNUSED_BUFFER1;

    while (count-- > 0)
        total = total + STEP_BUFFER1;
#if defined(MODE_BUFFER1) && MODE_BUFFER1 > 1
    total = total + 1;
#endif

    return total;
}
#else
int walk_buffer(int count) { return -count; }
#endif

#define FIELD_CURSOR2(name) field_cursor_##name
#define TEXT_CURSOR2(x) #x

struct holder_cursor {
    int FIELD_CURSOR2(low);
    int FIELD_CURSOR2(high);
};

int paste_cursor(int base) {
    struct holder_cursor held;

    held.FIELD_CURSOR2(low) = base;
    held.FIELD_CURSOR2(high) = base + 2;

    return held.FIELD_CURSOR2(high) - held.FIELD_CURSOR2(low)
           + (int) sizeof TEXT_CURSOR2(base + 1);
}

#define SWAP_HEADER3(a, b) do { \
        int swapped_ = (a); \
        (a) = (b); \
        (b) = swapped_; \
    } while (0)
#define FIRST_HEADER3(first, ...) (first)
#define COUNT_HEADER3(...) (sizeof((int[]){ __VA_ARGS__ }) / sizeof(int))

int order_header(int low, int high) {
    if (low > high)
        SWAP_HEADER3(low, high);

    return high - low + FIRST_HEADER3(3, 9, 8) + (int) COUNT_HEADER3(1, 2, 3);
}

#define ADD_MARGIN4(a, b) ((a) + (b))
#define TWICE_MARGIN4(a) ADD_MARGIN4(a, a)
#define QUAD_MARGIN4(a) TWICE_MARGIN4(TWICE_MARGIN4(a))

int nest_margin(int value) {
    int result = QUAD_MARGIN4(value) - ADD_MARGIN4(value, 4);

#undef ADD_MARGIN4
#define ADD_MARGIN4(a, b) ((a) - (b))
    return result + ADD_MARGIN4(value, 1);
}

#define ODD_MARKER5(v) ((v) & 1)
#define PICK_MARKER5(v) (ODD_MARKER5(v) ? (v) * 3 + 1 : (v) / 2)
#if (PICK_MARKER5(6) == 3) && !defined(NOWHERE_MARKER5)
# define STEPS_MARKER5 4
#else
# define STEPS_MARKER5 0
#endif

int collatz_marker(int value) {
    int steps = 0;

    while (value != 1 && steps < STEPS_MARKER5 * 10) {
        value = PICK_MARKER5(value);
        steps++;
    }

    return steps + __LINE__ % 3;
}

